import { render as remoteRender } from '@remote-ui/react';
import { mount } from './mount';
export const render = (element) => {
    const wrapper = mount((root) => remoteRender(element, root));
    /**
     * Adding an update method that flushes promises and then triggers an update via act. This is
     * needed when mocking APIs and other promise-based functions.
     */
    const update = async () => {
        await new Promise((resolve) => {
            setTimeout(resolve, 0);
        });
        wrapper.act(() => null);
    };
    return {
        wrapper,
        update,
    };
};
